script_template = "SHELL ({parameters}) {wait}"
cmd_script_template = 'SHELL ("C:/windows/system32/cmd.exe" /c {parameters}) {wait}'


class ShellCommand(object):

    def __init__(self, parameters, wait=False):
        """

        :param parameters: This is the shell command and must be contained
        within brackets, including any attributes. Any path
        names must be contained in quotes
        :param wait:Defines whether the script waits for the application to
        close before continuing or continues without waiting.
        False = Continue script execution
        True = Wait for application to complete before continuing script execution
        """
        self.parameters = parameters
        self.wait = wait

    def __str__(self):
        return script_template.format(parameters=self.parameters, wait=int(self.wait))

    def __add__(self, other):
        return str(self) + "\n" + str(other)

    def __radd__(self, other):
        return str(other) + "\n" + str(self)


class ShellCMDCommand(object):
    def __init__(self, parameters, wait=False):
        """
                :param parameters: This is the shell command which starts with C:/windows/system32/cmd.exe and must be contained
        within brackets, including any attributes. Any path
        names must be contained in quotes
        :param wait:Defines whether the script waits for the application to
        close before continuing or continues without waiting.
        False = Continue script execution
        True = Wait for application to complete before continuing script execution
        """
        self.parameters = parameters
        self.wait = wait

    def __str__(self):
        return cmd_script_template.format(parameters=self.parameters, wait=int(self.wait))

    def __add__(self, other):
        return str(self) + "\n" + str(other)

    def __radd__(self, other):
        return str(other) + "\n" + str(self)
